result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/logrotate_mini.py", "content": "#!/usr/bin/env python3
"""logrotate_mini.py -- minimal stdlib-only log rotator driven by rotate.json.

Config format (list of entries):
    [
        {"path": "logs/app.log", "max_bytes": 1024, "keep": 3, "compress": true}
    ]

When a log exceeds max_bytes:
    - the oldest kept rotation is deleted
    - existing rotations are shifted up by one slot
    - the live log becomes rotation #1 (gzipped as *.1.gz when compress=true)
    - an empty live log is recreated

Use --dry-run to print every action that WOULD be taken without touching files.
"""

import argparse
import gzip
import json
import os
import shutil
import sys


# ---------------------------------------------------------------- actions ----

def _do_remove(target):
    os.remove(target)


def _do_rename(src, dst):
    os.replace(src, dst)


def _do_compress(src, dst):
    with open(src, "rb") as fin, gzip.open(dst, "wb") as fout:
        shutil.copyfileobj(fin, fout)
    os.remove(src)


def _do_create_empty(path):
    with open(path, "w"):
        pass


# ------------------------------------------------------------- rotation ------

def _slot_names(base, slot):
    """Possible filenames for a given rotation slot (compressed and plain)."""
    return ["{}.{}.gz".format(base, slot), "{}.{}".format(base, slot)]


def _shift_dest(src, base, slot):
    """Destination name when shifting a file in `slot` up to `slot + 1`."""
    suffix = ".gz" if src.endswith(".gz") else ""
    return "{}.{}{}".format(base, slot + 1, suffix)


def rotate_log(path, max_bytes, keep, compress, dry_run=False):
    """Rotate a single log file. Prints actions instead of performing them
    when dry_run is True. Returns True if a rotation was needed."""
    if keep < 1:
        raise ValueError("keep must be >= 1")
    if not os.path.exists(path) or os.path.getsize(path) <= max_bytes:
        return False

    def emit(message):
        print("[dry-run] {}".format(message))

    def report(text):
        if dry_run:
            emit(text)

    # 1. Delete the oldest rotation (beyond `keep`).
    for old in _slot_names(path, keep):
        if os.path.exists(old):
            report("delete {}".format(old))
            if not dry_run:
                _do_remove(old)

    # 2. Shift existing rotations up: slot N-1 -> N, ..., slot 1 -> 2.
    for slot in range(keep - 1, 0, -1):
        for src in _slot_names(path, slot):
            if os.path.exists(src):
                dst = _shift_dest(src, path, slot)
                report("rename {} -> {}".format(src, dst))
                if not dry_run:
                    _do_rename(src, dst)
                break  # only one variant of each slot exists

    # 3. Rotate the live log into slot 1.
    if compress:
        dst = "{}.1.gz".format(path)
        report("compress {} -> {}".format(path, dst))
        if not dry_run:
            _do_compress(path, dst)
    else:
        dst = "{}.1".format(path)
        report("rename {} -> {}".format(path, dst))
        if not dry_run:
            _do_rename(path, dst)

    # 4. Recreate an empty live log so the application keeps writing.
    report("create {}".format(path))
    if not dry_run:
        _do_create_empty(path)
    return True


def load_config(config_path):
    with open(config_path, "r", encoding="utf-8") as fh:
        entries = json.load(fh)
    if not isinstance(entries, list):
        raise ValueError("config root must be a JSON list")
    base_dir = os.path.dirname(os.path.abspath(config_path))
    resolved = []
    for entry in entries:
        path = entry["path"]
        if not os.path.isabs(path):
            path = os.path.join(base_dir, path)
        resolved.append({
            "path": path,
            "max_bytes": int(entry["max_bytes"]),
            "keep": int(entry["keep"]),
            "compress": bool(entry.get("compress", False)),
        })
    return resolved


def rotate_all(config_path, dry_run=False):
    """Run rotation for every entry in the config. Returns number of logs rotated."""
    count = 0
    for entry in load_config(config_path):
        if rotate_log(dry_run=dry_run, **entry):
            count += 1
    return count


def main(argv=None):
    parser = argparse.ArgumentParser(description="Minimal stdlib log rotator.")
    parser.add_argument("config", nargs="?", default="rotate.json",
                        help="path to rotate.json (default: ./rotate.json)")
    parser.add_argument("--dry-run", action="store_true",
                        help="print actions without touching any files")
    args = parser.parse_args(argv)

    try:
        rotate_all(args.config, dry_run=args.dry_run)
    except (OSError, ValueError, KeyError, json.JSONDecodeError) as exc:
        print("error: {}".format(exc), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
